head.b:skin:
/* ============================================
   CSS VARIABLES - ENHANCED
   ============================================ */
:root {
  /* Islamic Color Palette - Enhanced */
  --primary: #1a472a;
  --primary-light: #2d7a4a;
  --primary-dark: #0f2e1a;
  --secondary: #2d5a27;
  --accent: #8e6e53;
  --accent-light: #b8957a;
  --gold: #c19a3f;
  --gold-light: #d4b15f;
  --gold-gradient: linear-gradient(135deg, #c19a3f, #e8c96a);
  --light-green: #e8f5e8;
  --white: #ffffff;
  --dark: #1a1a1a;
  --text: #2c3e2c;
  --text-light: #5a6b5a;
  --light-bg: #f8fbf8;
  --gray-light: #f5f5f5;
  --gray-medium: #e0e0e0;
  --gray-dark: #757575;

  /* Font Sizes */
  --bengali-font-size: 16px;
  --arabic-font-size: 1.6rem;
  --ui-font-size: 1rem;

  /* Font Families */
  --font-bengali: 'Kalpurush', 'Hind Siliguri', sans-serif;
  --font-arabic: 'Amiri', 'Scheherazade New', serif;
  --font-ui: 'Hind Siliguri', sans-serif;

  /* Enhanced Shadows */
  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.06);
  --shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
  --shadow-hover: 0 8px 32px rgba(0, 0, 0, 0.12);
  --shadow-large: 0 16px 48px rgba(0, 0, 0, 0.15);
  --shadow-glow: 0 0 30px rgba(193, 154, 63, 0.15);

  /* Border Radius */
  --rounded: 10px;
  --rounded-lg: 18px;
  --rounded-xl: 24px;
  --rounded-full: 50px;

  /* Transitions */
  --transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
  --transition-slow: all 0.6s cubic-bezier(0.25, 0.8, 0.25, 1);
  --transition-bounce: all 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55);

  /* Gradient */
  --header-gradient: linear-gradient(135deg, #1a472a, #2d7a4a);
  --hero-overlay: linear-gradient(135deg, rgba(26, 71, 42, 0.92), rgba(45, 90, 39, 0.85));
}

/* Dark Mode - Enhanced */
[data-theme="dark"] {
  --primary: #3a9a5f;
  --primary-light: #4ab070;
  --primary-dark: #1a3a2a;
  --secondary: #4a8a5f;
  --accent: #b8957a;
  --accent-light: #d4b09a;
  --gold: #e8c96a;
  --gold-light: #f0d97a;
  --light-green: #1a2a1a;
  --white: #1e1e1e;
  --dark: #f0f0f0;
  --text: #e0e0e0;
  --text-light: #b0b0b0;
  --light-bg: #121212;
  --gray-light: #2a2a2a;
  --gray-medium: #3a3a3a;
  --gray-dark: #a0a0a0;
  --shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  --shadow-hover: 0 8px 32px rgba(0, 0, 0, 0.4);
  --shadow-large: 0 16px 48px rgba(0, 0, 0, 0.5);
  --shadow-glow: 0 0 30px rgba(232, 201, 106, 0.1);
}

/* ============================================
   RESET & BASE
   ============================================ */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-bengali);
  color: var(--text);
  background: var(--light-bg);
  line-height: 1.8;
  overflow-x: hidden;
  font-size: var(--bengali-font-size);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  transition: background-color 0.4s ease, color 0.4s ease;
  min-height: 100vh;
}

body.modal-open {
  overflow: hidden;
}

/* Scrollbar Styling */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}
::-webkit-scrollbar-track {
  background: var(--gray-light);
  border-radius: 10px;
}
::-webkit-scrollbar-thumb {
  background: var(--primary);
  border-radius: 10px;
  transition: var(--transition);
}
::-webkit-scrollbar-thumb:hover {
  background: var(--gold);
}

/* ============================================
   TYPOGRAPHY - ENHANCED
   ============================================ */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.3;
  margin-top: 0;
  color: var(--primary);
  font-family: var(--font-ui);
}

h1 { font-size: 2.8rem; letter-spacing: -0.02em; }
h2 { font-size: 2.2rem; letter-spacing: -0.01em; }
h3 { font-size: 1.6rem; }
h4 { font-size: 1.3rem; }
h5 { font-size: 1.1rem; }
h6 { font-size: 1rem; }

p {
  margin-bottom: 1.5rem;
  font-size: 1.1rem;
  color: var(--text);
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
}

a:hover {
  color: var(--gold);
}

.text-gradient {
  background: var(--gold-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* ============================================
   CONTAINER
   ============================================ */
.container {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 2rem;
}

/* ============================================
   HEADER - ENHANCED
   ============================================ */
.agency-header {
  background: var(--white);
  box-shadow: var(--shadow-sm);
  position: sticky;
  top: 0;
  z-index: 1000;
  padding: 0.6rem 0;
  transition: var(--transition);
  border-bottom: 3px solid transparent;
  backdrop-filter: blur(10px);
  background: rgba(255, 255, 255, 0.95);
}

[data-theme="dark"] .agency-header {
  background: rgba(30, 30, 30, 0.95);
}

.header-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--primary);
  text-decoration: none;
  transition: var(--transition);
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.logo:hover {
  color: var(--gold);
  transform: translateY(-2px);
}

.logo img {
  height: 45px;
  width: auto;
  transition: var(--transition);
}

.logo img:hover {
  transform: rotate(-5deg) scale(1.05);
}

.logo span {
  background: var(--gold-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Navigation - Enhanced */
.nav-menu {
  display: flex;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 0.5rem;
  flex-wrap: wrap;
  align-items: center;
}

.nav-item {
  position: relative;
}

.nav-link {
  color: var(--text);
  text-decoration: none;
  font-weight: 600;
  padding: 0.6rem 1.2rem;
  transition: var(--transition);
  display: inline-block;
  border-radius: var(--rounded-full);
  font-size: 1rem;
  font-family: var(--font-ui);
  position: relative;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 2px;
  background: var(--gold);
  transition: var(--transition);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 60%;
}

.nav-link:hover {
  color: var(--primary);
  background: rgba(26, 71, 42, 0.06);
}

.nav-link.active {
  color: var(--primary);
  font-weight: 700;
  background: rgba(26, 71, 42, 0.08);
}

/* Theme Toggle - Enhanced */
.theme-toggle {
  background: var(--gray-light);
  border: 2px solid var(--gray-medium);
  cursor: pointer;
  font-size: 1.3rem;
  padding: 0.5rem;
  border-radius: var(--rounded-full);
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  position: relative;
  overflow: hidden;
}

.theme-toggle:hover {
  background: rgba(26, 71, 42, 0.1);
  border-color: var(--primary);
  transform: rotate(30deg) scale(1.05);
}

.theme-toggle #theme-icon {
  transition: var(--transition);
}

/* ============================================
   HERO SECTION - ENHANCED
   ============================================ */
.hero-section {
  background: var(--hero-overlay);
  color: var(--white);
  padding: 8rem 2rem 7rem;
  text-align: center;
  position: relative;
  overflow: hidden;
  background-image: url('https://images.unsplash.com/photo-1541250623744-9ac4f8c56c5f?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80');
  background-size: cover;
  background-position: center;
  background-blend-mode: overlay;
  min-height: 600px;
  display: flex;
  align-items: center;
}

.hero-section::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.3);
  z-index: 0;
}

.hero-section::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  right: 0;
  height: 80px;
  background: linear-gradient(to top, var(--light-bg), transparent);
  z-index: 0;
}

[data-theme="dark"] .hero-section::after {
  background: linear-gradient(to top, var(--light-bg), transparent);
}

.hero-content {
  position: relative;
  z-index: 1;
  max-width: 900px;
  margin: 0 auto;
}

.hero-title {
  font-size: 4rem;
  margin-bottom: 1.5rem;
  font-weight: 700;
  line-height: 1.15;
  text-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  animation: fadeInUp 0.8s ease;
  font-family: var(--font-arabic);
  color: var(--white);
}

.hero-title .highlight {
  color: var(--gold-light);
}

.hero-subtitle {
  font-size: 1.5rem;
  max-width: 750px;
  margin: 0 auto 3rem;
  opacity: 0.95;
  animation: fadeInUp 1s ease 0.2s forwards;
  opacity: 0;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.4);
  font-weight: 400;
  line-height: 1.7;
}

.hero-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  justify-content: center;
  animation: fadeInUp 1.2s ease 0.4s forwards;
  opacity: 0;
}

/* ============================================
   BUTTONS - ENHANCED
   ============================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.6rem;
  padding: 0.9rem 2.2rem;
  border-radius: var(--rounded-full);
  font-weight: 600;
  text-decoration: none;
  transition: var(--transition);
  border: none;
  cursor: pointer;
  text-align: center;
  box-shadow: var(--shadow-sm);
  font-family: var(--font-ui);
  font-size: var(--ui-font-size);
  position: relative;
  overflow: hidden;
  min-height: 48px;
}

.btn::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.2);
  transform: translate(-50%, -50%);
  transition: width 0.6s, height 0.6s;
}

.btn:hover::before {
  width: 300px;
  height: 300px;
}

.btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none !important;
}

.btn-primary {
  background: var(--gold-gradient);
  color: var(--dark);
  box-shadow: 0 4px 15px rgba(193, 154, 63, 0.3);
}

.btn-primary:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 8px 30px rgba(193, 154, 63, 0.4);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--white);
  color: var(--white);
}

.btn-outline:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.15);
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 8px 25px rgba(255, 255, 255, 0.15);
}

.btn-read-more {
  background: var(--primary);
  color: var(--white);
  padding: 0.7rem 1.8rem;
  font-size: 0.95rem;
}

.btn-read-more:hover:not(:disabled) {
  background: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.btn-secondary {
  background: var(--secondary);
  color: var(--white);
}

.btn-secondary:hover:not(:disabled) {
  background: var(--primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.btn-gold {
  background: var(--gold-gradient);
  color: var(--dark);
}

.btn-gold:hover:not(:disabled) {
  transform: translateY(-3px) scale(1.02);
  box-shadow: 0 8px 30px rgba(193, 154, 63, 0.4);
}

/* ============================================
   SECTION TITLES - ENHANCED
   ============================================ */
.section-title {
  text-align: center;
  font-size: 2.5rem;
  margin-bottom: 2.5rem;
  color: var(--primary);
  position: relative;
  padding-bottom: 1.2rem;
}

.section-title:after {
  content: '✦';
  position: absolute;
  bottom: -10px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 1rem;
  color: var(--gold);
  background: var(--light-bg);
  padding: 0 0.5rem;
}

.section-title:before {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 80px;
  height: 3px;
  background: var(--gold-gradient);
  border-radius: 2px;
}

/* ============================================
   DAILY SECTION - ENHANCED
   ============================================ */
.daily-section {
  margin-bottom: 4rem;
  width: 100%;
  max-width: none;
  padding: 1rem 0;
}

.daily-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2rem;
  margin-bottom: 2rem;
  width: 100%;
}

.daily-card {
  background: var(--white);
  border-radius: var(--rounded-lg);
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow);
  transition: var(--transition);
  text-align: center;
  border: 1px solid rgba(0,0,0,0.04);
  position: relative;
  overflow: hidden;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.daily-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-hover);
}

.daily-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--gold-gradient);
  opacity: 0;
  transition: var(--transition);
}

.daily-card:hover::before {
  opacity: 1;
}

.daily-card-icon {
  font-size: 2.8rem;
  color: var(--primary);
  margin-bottom: 1rem;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 80px;
  height: 80px;
  background: rgba(26, 71, 42, 0.08);
  border-radius: 50%;
  margin: 0 auto 1.2rem;
  transition: var(--transition);
}

.daily-card:hover .daily-card-icon {
  background: rgba(193, 154, 63, 0.15);
  transform: scale(1.1) rotate(-5deg);
}

.daily-card-title {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--primary);
  position: relative;
  padding-bottom: 0.8rem;
}

.daily-card-title:after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 40px;
  height: 2px;
  background: var(--gold);
  transition: var(--transition);
}

.daily-card:hover .daily-card-title:after {
  width: 80px;
}

.arabic-text {
  font-family: var(--font-arabic);
  font-size: var(--arabic-font-size);
  text-align: right;
  direction: rtl;
  padding: 1.8rem;
  background: var(--light-green);
  border-radius: var(--rounded);
  margin: 1rem 0 1.5rem;
  line-height: 2.2;
  box-shadow: inset 0 0 5px rgba(0,0,0,0.03);
  flex-grow: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 400;
  letter-spacing: 0.5px;
}

/* Islamic Border - Enhanced */
.islamic-border {
  position: relative;
  border: 2px solid var(--gold);
  border-radius: var(--rounded);
  padding: 2rem;
  background: var(--white);
  margin: 1rem 0;
}

.islamic-border::before {
  content: "﷽";
  position: absolute;
  top: -18px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  padding: 0 12px;
  font-family: var(--font-arabic);
  font-size: 1.6rem;
  color: var(--gold);
  z-index: 1;
}

/* ============================================
   BLOG SECTION - ENHANCED
   ============================================ */
.blog-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(350px, 1fr));
  gap: 2.5rem;
  margin-bottom: 3rem;
}

.blog-post {
  background: var(--white);
  border-radius: var(--rounded-lg);
  padding: 2.2rem 2rem;
  box-shadow: var(--shadow);
  transition: var(--transition);
  border-left: 4px solid var(--primary);
  display: flex;
  flex-direction: column;
  height: 100%;
  position: relative;
  overflow: hidden;
}

.blog-post::after {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  width: 80px;
  height: 80px;
  background: var(--gold-gradient);
  opacity: 0.05;
  border-radius: 0 0 0 80px;
  transition: var(--transition);
}

.blog-post:hover::after {
  width: 120px;
  height: 120px;
  opacity: 0.08;
}

.blog-post:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-hover);
  border-left-color: var(--gold);
}

.post-title {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: var(--primary);
  line-height: 1.4;
}

.post-title a {
  color: var(--primary);
  transition: var(--transition);
}

.post-title a:hover {
  color: var(--gold);
}

.post-meta {
  color: var(--gray-dark);
  font-size: 0.9rem;
  margin-bottom: 1rem;
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
  align-items: center;
}

.post-meta span {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}

.post-excerpt {
  margin-bottom: 1.5rem;
  flex-grow: 1;
  color: var(--text);
  line-height: 1.7;
}

.post-read-more {
  margin-top: auto;
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
}

/* Full Post Content - Enhanced */
.post-content-full {
  background: var(--white);
  border-radius: var(--rounded-lg);
  padding: 3.5rem;
  box-shadow: var(--shadow);
  margin-bottom: 3rem;
  border-left: 4px solid var(--gold);
  max-width: 900px;
  margin-left: auto;
  margin-right: auto;
}

.post-content-full .post-title {
  font-size: 2.8rem;
  margin-bottom: 1.5rem;
  color: var(--primary);
  line-height: 1.25;
}

.post-content-full .post-meta {
  font-size: 1rem;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--gray-medium);
}

.post-content-full .post-body {
  font-size: 1.1rem;
  line-height: 1.9;
  color: var(--text);
}

.post-content-full .post-body p {
  margin-bottom: 1.5rem;
}

.post-content-full .post-body h2,
.post-content-full .post-body h3,
.post-content-full .post-body h4 {
  margin: 2.5rem 0 1.2rem 0;
  color: var(--primary);
}

.post-content-full .post-body blockquote {
  border-left: 4px solid var(--gold);
  padding-left: 1.8rem;
  margin: 2rem 0;
  font-style: italic;
  color: var(--text-light);
  background: var(--light-green);
  padding: 1.8rem 2rem;
  border-radius: 0 var(--rounded) var(--rounded) 0;
}

.post-content-full .post-body img {
  max-width: 100%;
  height: auto;
  border-radius: var(--rounded);
  margin: 2rem 0;
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.post-content-full .post-body img:hover {
  box-shadow: var(--shadow-hover);
  transform: scale(1.01);
}

.post-content-full .post-body ul,
.post-content-full .post-body ol {
  padding-left: 2rem;
  margin: 1.5rem 0;
}

.post-content-full .post-body li {
  margin-bottom: 0.5rem;
}

/* Post Footer - Enhanced */
.post-footer {
  margin-top: 3.5rem;
  padding-top: 2.5rem;
  border-top: 1px solid var(--gray-medium);
}

.post-tags {
  margin-bottom: 2rem;
}

.post-tags h4 {
  margin-bottom: 1rem;
  color: var(--primary);
  font-size: 1.1rem;
}

.tags-list {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
}

.tag {
  background: var(--light-green);
  color: var(--primary);
  padding: 0.4rem 1.2rem;
  border-radius: var(--rounded-full);
  font-size: 0.9rem;
  text-decoration: none;
  transition: var(--transition);
  border: 1px solid transparent;
}

.tag:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.post-share h4 {
  margin-bottom: 1rem;
  color: var(--primary);
  font-size: 1.1rem;
}

.share-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.share-btn {
  background: var(--primary);
  color: var(--white);
  border: none;
  padding: 0.8rem 1.8rem;
  border-radius: var(--rounded);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-ui);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-weight: 600;
  font-size: 0.95rem;
}

.share-btn:hover {
  background: var(--primary-light);
  transform: translateY(-3px) scale(1.02);
  box-shadow: var(--shadow-hover);
}

/* ============================================
   CHATBOT - ENHANCED
   ============================================ */
.chatbot-section {
  background: var(--white);
  margin: 4rem 0;
  border-radius: var(--rounded-xl);
  box-shadow: var(--shadow-large);
  overflow: hidden;
  border: 1px solid rgba(0,0,0,0.04);
  width: 100%;
  max-width: none;
  position: relative;
  z-index: 1;
  transition: var(--transition);
}

.chatbot-section:hover {
  box-shadow: var(--shadow-large);
}

.chatbot-container {
  width: 100%;
  height: 100%;
}

#chatbot-header {
  background: var(--header-gradient);
  color: var(--white);
  padding: 1.5rem 2.5rem;
  font-size: 1.4rem;
  font-weight: 700;
  text-align: center;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
  position: relative;
  z-index: 100;
  transition: var(--transition);
  width: 100%;
  box-sizing: border-box;
}

#chatbot-header span {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

#chatbot-header span::before {
  content: '🕌';
  font-size: 1.8rem;
}

.chatbot-controls {
  display: flex;
  gap: 0.6rem;
  flex-wrap: wrap;
}

.chatbot-control-btn {
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--white);
  padding: 0.5rem 1.2rem;
  border-radius: var(--rounded-full);
  cursor: pointer;
  transition: var(--transition);
  font-size: 0.9rem;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 0.4rem;
  backdrop-filter: blur(5px);
}

.chatbot-control-btn:hover {
  background: rgba(255,255,255,0.25);
  transform: translateY(-2px) scale(1.02);
}

#chatbot-body {
  overflow-y: auto;
  padding: 2rem 2.5rem;
  background: var(--white);
  min-height: 420px;
  max-height: 500px;
  scrollbar-width: thin;
  scrollbar-color: var(--primary) var(--gray-light);
  transition: var(--transition);
}

[data-theme="dark"] #chatbot-body {
  background: var(--white);
}

#chatbot-body::-webkit-scrollbar {
  width: 6px;
}

#chatbot-body::-webkit-scrollbar-track {
  background: var(--gray-light);
  border-radius: 10px;
}

#chatbot-body::-webkit-scrollbar-thumb {
  background: var(--gold-gradient);
  border-radius: 10px;
}

#chatbot-input-container {
  display: flex;
  padding: 1.5rem 2.5rem;
  background: var(--light-green);
  border-top: 1px solid var(--gray-medium);
  gap: 0.8rem;
  align-items: center;
  flex-wrap: wrap;
  position: relative;
  transition: var(--transition);
  z-index: 100;
  width: 100%;
  box-sizing: border-box;
}

#chatbot-input {
  flex: 1;
  min-width: 200px;
  padding: 1rem 1.5rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded-full);
  outline: none;
  font-family: var(--font-ui);
  transition: var(--transition);
  font-size: var(--ui-font-size);
  background: var(--white);
  color: var(--text);
}

#chatbot-input:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 4px rgba(26, 71, 42, 0.08);
}

#chatbot-input:disabled {
  background: var(--gray-light);
  cursor: not-allowed;
}

/* Enhanced Messages */
.message {
  margin-bottom: 1.5rem;
  padding: 1.2rem 1.8rem;
  border-radius: 1.2rem;
  max-width: 85%;
  word-wrap: break-word;
  line-height: 1.7;
  position: relative;
  animation: fadeInUp 0.4s ease;
  font-size: var(--ui-font-size);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.message:hover {
  box-shadow: var(--shadow);
}

.message.user {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  margin-left: auto;
  border-bottom-right-radius: 0.4rem;
  color: #0d47a1;
  border: 1px solid #90caf9;
}

[data-theme="dark"] .message.user {
  background: linear-gradient(135deg, #1a2a4a, #0d1a3a);
  color: #90caf9;
  border-color: #1a3a5a;
}

.message.bot {
  background: linear-gradient(135deg, var(--light-green), #e8f5e8);
  margin-right: auto;
  border-bottom-left-radius: 0.4rem;
  color: var(--text);
  border: 1px solid #c8e6c9;
}

[data-theme="dark"] .message.bot {
  background: linear-gradient(135deg, #1a2a1a, #0d1a0d);
  border-color: #2a4a2a;
}

.message.bot.error {
  background: linear-gradient(135deg, #ffebee, #ffcdd2);
  border-color: #ef9a9a;
  color: #c62828;
}

.message.bot.success {
  background: linear-gradient(135deg, #e8f5e9, #c8e6c9);
  border-color: #81c784;
  color: #2e7d32;
}

.message.bot.info {
  background: linear-gradient(135deg, #e3f2fd, #bbdefb);
  border-color: #64b5f6;
  color: #0d47a1;
}

.message-timestamp {
  font-size: 0.7rem;
  color: var(--gray-dark);
  margin-top: 0.5rem;
  opacity: 0.7;
}

.quick-actions {
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
  margin: 1.5rem 0;
}

.quick-action-btn {
  background: var(--white);
  border: 2px solid var(--gray-medium);
  padding: 0.7rem 1.4rem;
  border-radius: var(--rounded-full);
  cursor: pointer;
  transition: var(--transition);
  font-family: var(--font-ui);
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--text);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.quick-action-btn:hover {
  border-color: var(--primary);
  background: rgba(26, 71, 42, 0.06);
  transform: translateY(-2px);
  box-shadow: var(--shadow-sm);
}

.quick-action-btn.secondary {
  border-color: var(--gray-medium);
  background: var(--gray-light);
}

.quick-action-btn.secondary:hover {
  border-color: var(--secondary);
  background: rgba(45, 90, 39, 0.06);
}

/* Typing Indicator */
.typing {
  padding: 1rem 1.8rem;
}

.typing-dots {
  display: flex;
  gap: 0.4rem;
  align-items: center;
}

.typing-dots span {
  width: 10px;
  height: 10px;
  background: var(--primary);
  border-radius: 50%;
  animation: typingBounce 1.4s infinite;
}

.typing-dots span:nth-child(2) {
  animation-delay: 0.2s;
}

.typing-dots span:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes typingBounce {
  0%, 60%, 100% { transform: translateY(0); opacity: 0.4; }
  30% { transform: translateY(-10px); opacity: 1; }
}

/* Search Highlight */
.search-highlight {
  background: var(--gold);
  color: var(--dark);
  padding: 0.1rem 0.3rem;
  border-radius: 3px;
  font-weight: 600;
}

.search-result-item {
  background: var(--white);
  padding: 1rem 1.5rem;
  margin: 0.8rem 0;
  border-radius: var(--rounded);
  border-left: 3px solid var(--gold);
  box-shadow: var(--shadow-sm);
  transition: var(--transition);
}

.search-result-item:hover {
  box-shadow: var(--shadow);
  transform: translateX(4px);
}

.search-result-sura {
  font-weight: 600;
  color: var(--primary);
  margin-bottom: 0.5rem;
}

.search-result-text {
  color: var(--text);
  line-height: 1.6;
}

/* ============================================
   TAFSIR MODAL - ENHANCED
   ============================================ */
.tafsir-modal {
  display: none;
  position: fixed;
  z-index: 10000;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.6);
  animation: fadeIn 0.3s;
  backdrop-filter: blur(4px);
}

.tafsir-modal-content {
  background: var(--white);
  margin: 5% auto;
  padding: 0;
  border-radius: var(--rounded-lg);
  width: 85%;
  max-width: 850px;
  box-shadow: var(--shadow-large);
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  animation: slideIn 0.3s;
}

.tafsir-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1.5rem 2rem;
  background: var(--header-gradient);
  color: white;
  border-radius: var(--rounded-lg) var(--rounded-lg) 0 0;
}

.tafsir-header h3 {
  margin: 0;
  font-size: 1.3rem;
  color: white;
}

.tafsir-controls {
  display: flex;
  gap: 0.8rem;
}

.tafsir-control-btn {
  background: rgba(255,255,255,0.15);
  border: none;
  color: white;
  cursor: pointer;
  font-size: 1.2rem;
  padding: 0.5rem 1rem;
  border-radius: var(--rounded);
  transition: var(--transition);
}

.tafsir-control-btn:hover {
  background: rgba(255,255,255,0.3);
  transform: translateY(-2px);
}

.tafsir-content {
  padding: 2rem;
  overflow-y: auto;
  flex-grow: 1;
  line-height: 1.8;
  color: var(--text);
}

.tafsir-verse {
  font-size: 1.6rem;
  text-align: right;
  margin-bottom: 1.5rem;
  padding: 1.5rem;
  background: var(--light-green);
  border-radius: var(--rounded);
  border-right: 4px solid var(--gold);
  font-family: var(--font-arabic);
  direction: rtl;
  line-height: 2;
}

.tafsir-explanation {
  margin-top: 1.5rem;
  font-size: 1.05rem;
  color: var(--text);
  line-height: 1.8;
}

.tafsir-source {
  margin-top: 1.5rem;
  font-style: italic;
  color: var(--gray-dark);
  font-size: 0.95rem;
  border-top: 1px solid var(--gray-medium);
  padding-top: 1.5rem;
}

.tafsir-action-buttons {
  display: flex;
  gap: 0.8rem;
  align-items: center;
  flex-wrap: wrap;
  margin: 1.5rem 0;
}

/* ============================================
   FOOTER - ENHANCED
   ============================================ */
.footer {
  background: var(--primary-dark);
  color: var(--white);
  padding: 4rem 0 2rem;
  margin-top: 4rem;
  position: relative;
  overflow: hidden;
}

.footer::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--gold-gradient);
}

.footer-content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 3rem;
  margin-bottom: 2.5rem;
}

.footer-widget h3 {
  color: var(--white);
  margin-bottom: 1.5rem;
  position: relative;
  padding-bottom: 0.8rem;
  font-size: 1.3rem;
}

.footer-widget h3:after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 40px;
  height: 2px;
  background: var(--gold);
}

.footer-widget p {
  color: rgba(255, 255, 255, 0.8);
  font-size: 1rem;
  line-height: 1.8;
}

.footer-links {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-links li {
  margin-bottom: 0.8rem;
}

.footer-links a {
  color: rgba(255, 255, 255, 0.8);
  text-decoration: none;
  transition: var(--transition);
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
}

.footer-links a:hover {
  color: var(--gold);
  padding-left: 8px;
  transform: translateX(4px);
}

.footer-bottom {
  text-align: center;
  padding-top: 2rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.95rem;
}

/* ============================================
   PANELS - ENHANCED
   ============================================ */
/* Fullscreen Tafsir */
#fullscreen-tafsir {
  display: none;
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: rgba(0, 0, 0, 0.92);
  z-index: 9999;
  padding: 2rem;
  overflow-y: auto;
  backdrop-filter: blur(10px);
}

#fullscreen-tafsir.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

#fullscreen-tafsir-content {
  max-width: 900px;
  margin: 2rem auto;
  background: var(--white);
  padding: 3rem;
  border-radius: var(--rounded-xl);
  box-shadow: var(--shadow-large);
  position: relative;
  animation: scaleIn 0.4s ease;
}

#fullscreen-tafsir-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 2px solid var(--gray-medium);
  flex-wrap: wrap;
  gap: 1rem;
}

#fullscreen-tafsir-title {
  font-size: 1.8rem;
  font-weight: 700;
  color: var(--primary);
}

#exit-fullscreen {
  background: var(--primary);
  color: var(--white);
  border: none;
  padding: 0.8rem 1.8rem;
  border-radius: var(--rounded);
  cursor: pointer;
  transition: var(--transition);
  font-weight: 600;
  font-family: var(--font-ui);
  display: flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 44px;
}

#exit-fullscreen:hover {
  background: var(--primary-light);
  transform: translateY(-2px);
  box-shadow: var(--shadow-hover);
}

.tafsir-container {
  background: #fffde7;
  padding: 2rem;
  border-radius: var(--rounded);
  margin-top: 1.5rem;
  border-left: 4px solid var(--gold);
  font-size: var(--ui-font-size);
  line-height: 2;
  color: var(--text);
}

/* Settings Panel - Enhanced */
.settings-panel {
  position: fixed;
  top: 0;
  right: -420px;
  width: 420px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-large);
  z-index: 9999;
  transition: var(--transition-slow);
  overflow-y: auto;
  padding: 2.5rem;
}

.settings-panel.open {
  right: 0;
}

.settings-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 2px solid var(--gray-medium);
}

.settings-title {
  font-size: 1.6rem;
  color: var(--primary);
  font-weight: 700;
}

.close-settings {
  background: none;
  border: none;
  font-size: 1.8rem;
  cursor: pointer;
  color: var(--gray-dark);
  transition: var(--transition);
  padding: 0.5rem;
}

.close-settings:hover {
  color: var(--primary);
  transform: rotate(90deg);
}

.setting-group {
  margin-bottom: 2rem;
}

.setting-label {
  display: block;
  margin-bottom: 0.8rem;
  font-weight: 600;
  color: var(--primary);
  font-size: 1.1rem;
}

.setting-select, .setting-input {
  width: 100%;
  padding: 0.9rem 1.2rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded);
  font-family: var(--font-ui);
  font-size: var(--ui-font-size);
  transition: var(--transition);
  background: var(--white);
  color: var(--text);
}

.setting-select:focus, .setting-input:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 4px rgba(26, 71, 42, 0.08);
}

.setting-description {
  font-size: 0.9rem;
  color: var(--gray-dark);
  margin-top: 0.5rem;
  line-height: 1.5;
}

/* Sura Panel - Enhanced */
.sura-panel {
  position: fixed;
  top: 0;
  left: -420px;
  width: 420px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-large);
  z-index: 9999;
  transition: var(--transition-slow);
  overflow-y: auto;
  padding: 2.5rem;
}

.sura-panel.open {
  left: 0;
}

.sura-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 2px solid var(--gray-medium);
}

.sura-title {
  font-size: 1.6rem;
  color: var(--primary);
  font-weight: 700;
}

.close-sura {
  background: none;
  border: none;
  font-size: 1.8rem;
  cursor: pointer;
  color: var(--gray-dark);
  transition: var(--transition);
  padding: 0.5rem;
}

.close-sura:hover {
  color: var(--primary);
  transform: rotate(90deg);
}

.search-container {
  padding: 0 0 1.5rem 0;
}

.search-container input {
  width: 100%;
  padding: 0.9rem 1.2rem;
  border: 2px solid var(--gray-medium);
  border-radius: var(--rounded-full);
  font-family: var(--font-ui);
  font-size: var(--ui-font-size);
  transition: var(--transition);
  background: var(--white);
  color: var(--text);
}

.search-container input:focus {
  border-color: var(--primary);
  outline: none;
  box-shadow: 0 0 0 4px rgba(26, 71, 42, 0.08);
}

.sura-list {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(85px, 1fr));
  gap: 0.8rem;
}

.sura-item {
  background: var(--light-green);
  border: 2px solid transparent;
  border-radius: var(--rounded);
  padding: 1rem 0.5rem;
  text-align: center;
  cursor: pointer;
  transition: var(--transition);
  font-weight: 600;
  color: var(--primary);
  font-size: 0.9rem;
}

.sura-item:hover {
  background: var(--primary);
  color: var(--white);
  transform: translateY(-3px) scale(1.02);
  box-shadow: var(--shadow);
}

.sura-item.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--gold);
}

.sura-item small {
  display: block;
  font-weight: 400;
  font-size: 0.7rem;
  opacity: 0.7;
  margin-top: 2px;
}

/* ============================================
   ANIMATIONS
   ============================================ */
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.92);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes slideIn {
  from { transform: translateY(-40px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* ============================================
   RESPONSIVE DESIGN
   ============================================ */
@media (max-width: 1200px) {
  .container { padding: 0 1.5rem; }
  .hero-title { font-size: 3.5rem; }
}

@media (max-width: 992px) {
  .hero-title { font-size: 3rem; }
  .hero-subtitle { font-size: 1.3rem; }
  .blog-grid { grid-template-columns: repeat(auto-fill, minmax(300px, 1fr)); }
  .section-title { font-size: 2.2rem; }
  .sura-panel, .settings-panel { width: 370px; }
  .post-content-full { padding: 2.5rem; }
}

@media (max-width: 768px) {
  .header-container { flex-direction: column; gap: 0.8rem; }
  .nav-menu { justify-content: center; gap: 0.3rem; }
  .nav-link { padding: 0.4rem 0.9rem; font-size: 0.9rem; }
  .hero-section { padding: 5rem 1rem 4rem; min-height: 450px; }
  .hero-title { font-size: 2.4rem; }
  .hero-subtitle { font-size: 1.1rem; margin-bottom: 2rem; }
  .daily-cards { grid-template-columns: 1fr; gap: 1.5rem; }
  .blog-grid { grid-template-columns: 1fr; gap: 1.5rem; }
  .post-content-full { padding: 1.8rem; margin: 0 1rem 2rem; }
  .post-content-full .post-title { font-size: 2.2rem; }
  .footer-content { grid-template-columns: 1fr; gap: 2rem; }
  .sura-panel, .settings-panel { width: 100%; left: -100%; right: auto; }
  .sura-panel.open { left: 0; }
  .settings-panel.open { right: 0; }
  #chatbot-header { padding: 1rem 1.5rem; font-size: 1.2rem; flex-direction: column; }
  #chatbot-body { padding: 1.5rem; min-height: 350px; max-height: 400px; }
  #chatbot-input-container { padding: 1rem 1.5rem; flex-direction: column; }
  #chatbot-input { min-width: auto; width: 100%; }
  .message { max-width: 95%; }
  .quick-actions { justify-content: center; }
  .tafsir-modal-content { width: 95%; margin: 2% auto; }
  .tafsir-action-buttons { flex-direction: column; width: 100%; }
  .tafsir-action-buttons button { width: 100%; }
  #fullscreen-tafsir-content { margin: 1rem; padding: 1.5rem; }
  #fullscreen-tafsir-title { font-size: 1.4rem; }
}

@media (max-width: 576px) {
  .container { padding: 0 1rem; }
  .hero-title { font-size: 2rem; }
  .hero-subtitle { font-size: 1rem; }
  .logo { font-size: 1.3rem; }
  .logo img { height: 35px; }
  .section-title { font-size: 1.8rem; }
  .daily-card { padding: 1.5rem; }
  .blog-post { padding: 1.5rem; }
  .arabic-text { font-size: 1.3rem; padding: 1rem; }
  .post-content-full { padding: 1.2rem; }
  .post-content-full .post-title { font-size: 1.8rem; }
  .sura-list { grid-template-columns: repeat(auto-fill, minmax(65px, 1fr)); }
  .settings-panel, .sura-panel { padding: 1.5rem; }
  .chatbot-controls { gap: 0.4rem; }
  .chatbot-control-btn { padding: 0.4rem 0.8rem; font-size: 0.8rem; }
  .share-buttons { flex-direction: column; width: 100%; }
  .share-btn { justify-content: center; width: 100%; }
  .btn { padding: 0.7rem 1.5rem; font-size: 0.9rem; }
}

@media (max-width: 400px) {
  .hero-title { font-size: 1.7rem; }
  .hero-subtitle { font-size: 0.9rem; }
  .daily-card-icon { width: 55px; height: 55px; font-size: 1.8rem; }
  .sura-list { grid-template-columns: repeat(auto-fill, minmax(55px, 1fr)); }
  .sura-item { padding: 0.7rem 0.3rem; font-size: 0.8rem; }
}

/* High Contrast Mode */
@media (prefers-contrast: high) {
  :root {
    --primary: #000000;
    --secondary: #1a1a1a;
    --gold: #ffd700;
    --text: #000000;
    --light-bg: #ffffff;
  }
  .hero-section::before { background: rgba(0, 0, 0, 0.7); }
  .btn-primary { border: 2px solid #000; }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Print Styles */
@media print {
  .agency-header, .footer, .chatbot-section, .quick-actions,
  .post-share, .sura-panel, .settings-panel, .tafsir-modal,
  #fullscreen-tafsir, .theme-toggle {
    display: none !important;
  }
  body { background: white; color: black; font-size: 12pt; }
  .container { max-width: none; padding: 0; }
  .post-content-full { box-shadow: none; border: none; padding: 0; }
  .arabic-text { background: white; border: 1px solid #ccc; }
  a { color: black; text-decoration: underline; }
}

body.script:
//
// Core initialization
document.addEventListener('DOMContentLoaded', function() {
    initializeEnhancedChatbot();
    initializeBlogFeatures();
    initializePanels();
    initializeEnhancedSettings();
    loadSuraList();
    initializeDailySection();
    initializeVoiceRecognition();
    initializeThemeToggle();
    initializeTimestamp();
    loadDailyAyat();
});

// ==================== UTILITY FUNCTIONS ====================
function initializeTimestamp() {
    const initialTimestamp = document.getElementById('initial-timestamp');
    if (initialTimestamp) {
        initialTimestamp.textContent = getCurrentTimestamp();
    }
}

function getCurrentTimestamp() {
    const now = new Date();
    return now.toLocaleTimeString('bn-BD', { 
        hour: '2-digit', 
        minute: '2-digit',
        hour12: true 
    });
}

// ==================== THEME TOGGLE ====================
function initializeThemeToggle() {
    const themeToggle = document.getElementById('theme-toggle');
    const themeIcon = document.getElementById('theme-icon');

    const savedTheme = localStorage.getItem('quranTheme');
    if (savedTheme) {
        document.documentElement.setAttribute('data-theme', savedTheme);
        updateThemeIcon(savedTheme);
    }

    themeToggle.addEventListener('click', function() {
        const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
        const newTheme = currentTheme === 'light' ? 'dark' : 'light';

        document.documentElement.setAttribute('data-theme', newTheme);
        localStorage.setItem('quranTheme', newTheme);
        updateThemeIcon(newTheme);
    });

    function updateThemeIcon(theme) {
        themeIcon.textContent = theme === 'dark' ? '☀️' : '🌙';
    }
}

// ==================== DAILY SECTION FUNCTIONS ====================
function loadDailyAyat() {
    const randomSurah = Math.floor(Math.random() * 114) + 1;
    const maxAyah = getSurahAyahCount(randomSurah);
    const randomAyah = Math.floor(Math.random() * maxAyah) + 1;

    loadQuranData().then(() => {
        const ayat = window.quranData.find(a => a.sura == randomSurah && a.aya == randomAyah);
        const arabic = window.arabicData.find(a => a.sura == randomSurah && a.VerseIDAr == randomAyah);

        if (ayat && arabic) {
            document.getElementById('daily-surah-name').textContent = `সূরা ${getSurahName(randomSurah)}, আয়াত ${randomAyah}`;
            document.getElementById('daily-arabic-text').innerHTML = arabic.ayat || 'لَا إِلَٰهَ إِلَّا اللَّهُ';
            document.getElementById('daily-translation').textContent = ayat.text;

            document.getElementById('daily-tafsir-btn').onclick = function() {
                showFullTafsir(randomSurah, randomAyah);
            };

            document.getElementById('daily-audio-btn').onclick = function() {
                playAyaAudio(randomSurah, randomAyah);
            };

            document.getElementById('daily-copy-btn').onclick = function() {
                copyAyaText(randomSurah, randomAyah);
            };
        }
    });
}

function getSurahName(surahNumber) {
    const suraNames = [
        "আল-ফাতিহা", "আল-বাকারা", "আল-ইমরান", "আন-নিসা", "আল-মায়িদাহ",
        "আল-আন'আম", "আল-আ'রাফ", "আল-আনফাল", "আত-তাওবাহ", "ইউনুস",
        "হুদ", "ইউসুফ", "আর-রাদ", "ইবরাহিম", "আল-হিজর",
        "আন-নাহল", "আল-ইসরা", "আল-কাহফ", "মারইয়াম", "তাহা"
    ];
    return suraNames[surahNumber - 1] || `সূরা ${surahNumber}`;
}

function getSurahAyahCount(surahNumber) {
    const ayahCounts = {
        1: 7, 2: 286, 3: 200, 4: 176, 5: 120, 6: 165, 7: 206, 8: 75, 9: 129, 10: 109,
        11: 123, 12: 111, 13: 43, 14: 52, 15: 99, 16: 128, 17: 111, 18: 110, 19: 98, 20: 135,
        21: 112, 22: 78, 23: 118, 24: 64, 25: 77, 26: 227, 27: 93, 28: 88, 29: 69, 30: 60,
        31: 34, 32: 30, 33: 73, 34: 54, 35: 45, 36: 83, 37: 182, 38: 88, 39: 75, 40: 85,
        41: 54, 42: 53, 43: 89, 44: 59, 45: 37, 46: 35, 47: 38, 48: 29, 49: 18, 50: 45,
        51: 60, 52: 49, 53: 62, 54: 55, 55: 78, 56: 96, 57: 29, 58: 22, 59: 24, 60: 13,
        61: 14, 62: 11, 63: 11, 64: 18, 65: 12, 66: 12, 67: 30, 68: 52, 69: 52, 70: 44,
        71: 28, 72: 28, 73: 20, 74: 56, 75: 40, 76: 31, 77: 50, 78: 40, 79: 46, 80: 42,
        81: 29, 82: 19, 83: 36, 84: 25, 85: 22, 86: 17, 87: 19, 88: 26, 89: 30, 90: 20,
        91: 15, 92: 21, 93: 11, 94: 8, 95: 8, 96: 19, 97: 5, 98: 8, 99: 8, 100: 11,
        101: 11, 102: 8, 103: 3, 104: 9, 105: 5, 106: 4, 107: 7, 108: 3, 109: 6, 110: 3,
        111: 5, 112: 4, 113: 5, 114: 6
    };
    return ayahCounts[surahNumber] || 0;
}

// ==================== PANELS MANAGEMENT ====================
function initializePanels() {
    const suraPanelBtn = document.getElementById('sura-panel-btn');
    const closeSura = document.getElementById('close-sura');
    const suraPanel = document.getElementById('sura-panel');
    const suraSearch = document.getElementById('sura-search');

    function openSuraPanel() {
        suraPanel.classList.add('open');
        document.body.style.overflow = 'hidden';
        if (suraSearch) suraSearch.focus();
    }

    function closeSuraPanel() {
        suraPanel.classList.remove('open');
        document.body.style.overflow = 'auto';
    }

    if (suraPanelBtn) suraPanelBtn.addEventListener('click', openSuraPanel);
    if (closeSura) closeSura.addEventListener('click', closeSuraPanel);

    if (suraSearch) {
        suraSearch.addEventListener('input', function(e) {
            const searchTerm = e.target.value.toLowerCase();
            const suraItems = document.querySelectorAll('.sura-item');

            suraItems.forEach(item => {
                const text = item.textContent.toLowerCase();
                if (text.includes(searchTerm)) {
                    item.style.display = 'block';
                } else {
                    item.style.display = 'none';
                }
            });
        });
    }

    const settingsPanelBtn = document.getElementById('settings-panel-btn');
    const closeSettings = document.getElementById('close-settings');
    const settingsPanel = document.getElementById('settings-panel');

    function openSettingsPanel() {
        settingsPanel.classList.add('open');
        document.body.style.overflow = 'hidden';
    }

    function closeSettingsPanel() {
        settingsPanel.classList.remove('open');
        document.body.style.overflow = 'auto';
    }

    if (settingsPanelBtn) settingsPanelBtn.addEventListener('click', openSettingsPanel);
    if (closeSettings) closeSettings.addEventListener('click', closeSettingsPanel);

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') {
            closeSuraPanel();
            closeSettingsPanel();
            closeFullscreenTafsir();
            exitFullscreenMode();
        }
    });

    document.addEventListener('click', function(e) {
        if (suraPanel.classList.contains('open') && !suraPanel.contains(e.target) && !suraPanelBtn.contains(e.target)) {
            closeSuraPanel();
        }
        if (settingsPanel.classList.contains('open') && !settingsPanel.contains(e.target) && !settingsPanelBtn.contains(e.target)) {
            closeSettingsPanel();
        }
    });
}

// ==================== ENHANCED SETTINGS MANAGEMENT ====================
function initializeEnhancedSettings() {
    const bengaliFontSize = document.getElementById('bengali-font-size');
    const arabicFontSize = document.getElementById('arabic-font-size');
    const bengaliFontFamily = document.getElementById('bengali-font-family');
    const arabicFontFamily = document.getElementById('arabic-font-family');
    const themeMode = document.getElementById('theme-mode');
    const audioSpeed = document.getElementById('audio-speed');
    const autoPlayAudio = document.getElementById('auto-play-audio');
    const showTransliteration = document.getElementById('show-transliteration');
    const resetSettings = document.getElementById('reset-settings');

    loadEnhancedSettings();

    if (bengaliFontSize) bengaliFontSize.addEventListener('change', saveEnhancedSettings);
    if (arabicFontSize) arabicFontSize.addEventListener('change', saveEnhancedSettings);
    if (bengaliFontFamily) bengaliFontFamily.addEventListener('change', saveEnhancedSettings);
    if (arabicFontFamily) arabicFontFamily.addEventListener('change', saveEnhancedSettings);
    if (themeMode) themeMode.addEventListener('change', saveEnhancedSettings);
    if (audioSpeed) audioSpeed.addEventListener('change', saveEnhancedSettings);
    if (autoPlayAudio) autoPlayAudio.addEventListener('change', saveEnhancedSettings);
    if (showTransliteration) showTransliteration.addEventListener('change', saveEnhancedSettings);
    if (resetSettings) resetSettings.addEventListener('click', resetAllSettings);

    function saveEnhancedSettings() {
        const settings = {
            bengaliFontSize: bengaliFontSize.value,
            arabicFontSize: arabicFontSize.value,
            bengaliFontFamily: bengaliFontFamily.value,
            arabicFontFamily: arabicFontFamily.value,
            themeMode: themeMode.value,
            audioSpeed: audioSpeed.value,
            autoPlayAudio: autoPlayAudio.checked,
            showTransliteration: showTransliteration.checked
        };
        localStorage.setItem('quranThemeSettings', JSON.stringify(settings));
        applyChatbotSettings(settings);
    }

    function loadEnhancedSettings() {
        const savedSettings = localStorage.getItem('quranThemeSettings');
        if (savedSettings) {
            const settings = JSON.parse(savedSettings);
            if (bengaliFontSize) bengaliFontSize.value = settings.bengaliFontSize;
            if (arabicFontSize) arabicFontSize.value = settings.arabicFontSize;
            if (bengaliFontFamily) bengaliFontFamily.value = settings.bengaliFontFamily;
            if (arabicFontFamily) arabicFontFamily.value = settings.arabicFontFamily;
            if (themeMode) themeMode.value = settings.themeMode;
            if (audioSpeed) audioSpeed.value = settings.audioSpeed;
            if (autoPlayAudio) autoPlayAudio.checked = settings.autoPlayAudio;
            if (showTransliteration) showTransliteration.checked = settings.showTransliteration;
            applyChatbotSettings(settings);
        }
    }

    function resetAllSettings() {
        localStorage.removeItem('quranThemeSettings');
        if (bengaliFontSize) bengaliFontSize.value = '16px';
        if (arabicFontSize) arabicFontSize.value = '1.6rem';
        if (bengaliFontFamily) bengaliFontFamily.value = 'Kalpurush, Hind Siliguri, sans-serif';
        if (arabicFontFamily) arabicFontFamily.value = 'Amiri, Scheherazade New, serif';
        if (themeMode) themeMode.value = 'light';
        if (audioSpeed) audioSpeed.value = '1';
        if (autoPlayAudio) autoPlayAudio.checked = false;
        if (showTransliteration) showTransliteration.checked = false;
        applyChatbotSettings({
            bengaliFontSize: '16px',
            arabicFontSize: '1.6rem',
            bengaliFontFamily: 'Kalpurush, Hind Siliguri, sans-serif',
            arabicFontFamily: 'Amiri, Scheherazade New, serif',
            themeMode: 'light',
            audioSpeed: '1',
            autoPlayAudio: false,
            showTransliteration: false
        });
    }

    function applyChatbotSettings(settings) {
        const chatbotSection = document.querySelector('.chatbot-section');

        if (chatbotSection) {
            chatbotSection.style.setProperty('--bengali-font-size', settings.bengaliFontSize);
            chatbotSection.style.setProperty('--arabic-font-size', settings.arabicFontSize);
            chatbotSection.style.setProperty('--font-bengali', settings.bengaliFontFamily);
            chatbotSection.style.setProperty('--font-arabic', settings.arabicFontFamily);
        }

        if (settings.themeMode === 'dark' || (settings.themeMode === 'auto' && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
            document.documentElement.setAttribute('data-theme', 'dark');
        } else {
            document.documentElement.setAttribute('data-theme', 'light');
        }

        window.audioSettings = {
            speed: settings.audioSpeed,
            autoPlay: settings.autoPlayAudio
        };

        window.displaySettings = {
            showTransliteration: settings.showTransliteration
        };
    }
}

// ==================== SURA LIST MANAGEMENT ====================
function loadSuraList() {
    const suraList = document.getElementById('sura-list');
    if (!suraList) return;

    const suraNames = [
        "আল-ফাতিহা", "আল-বাকারা", "আল-ইমরান", "আন-নিসা", "আল-মায়িদাহ",
        "আল-আন'আম", "আল-আ'রাফ", "আল-আনফাল", "আত-তাওবাহ", "ইউনুস",
        "হুদ", "ইউসুফ", "আর-রাদ", "ইবরাহিম", "আল-হিজর",
        "আন-নাহল", "আল-ইসরা", "আল-কাহফ", "মারইয়াম", "তাহা",
        "আল-আম্বিয়া", "আল-হাজ্জ", "আল-মুমিনুন", "আন-নূর", "আল-ফুরকান",
        "আশ-শু'আরা", "আন-নামল", "আল-কাসাস", "আল-আনকাবুত", "আর-রুম",
        "লুকমান", "আস-সাজদাহ", "আল-আহযাব", "সাবা", "ফাতির",
        "ইয়াসিন", "আস-সাফফাত", "সাদ", "আয-যুমার", "গাফির",
        "ফুসসিলাত", "আশ-শুরা", "আয-যুখরুফ", "আদ-দুখান", "আল-জাসিয়াহ",
        "আল-আহকাফ", "মুহাম্মদ", "আল-ফাতহ", "আল-হুজুরাত", "কাফ",
        "আয-যারিয়াত", "আত-তুর", "আন-নাজম", "আল-কামার", "আর-রহমান",
        "আল-ওয়াকিয়াহ", "আল-হাদীদ", "আল-মুজাদিলাহ", "আল-হাশর", "আল-মুমতাহিনাহ",
        "আস-সাফ", "আল-জুমু'আহ", "আল-মুনাফিকুন", "আত-তাগাবুন", "আত-তালাক",
        "আত-তাহরীম", "আল-মুলক", "আল-কালাম", "আল-হাক্কাহ", "আল-মা'আরিজ",
        "নূহ", "আল-জিন", "আল-মুজাম্মিল", "আল-মুদ্দাস্সির", "আল-কিয়ামাহ",
        "আল-ইনসান", "আল-মুরসালাত", "আন-নাবা", "আন-নাজি'আত", "আবাসা",
        "আত-তাকভীর", "আল-ইনফিতার", "আল-মুতাফফিফীন", "আল-ইনশিকাক", "আল-বুরূজ",
        "আত-তারিক", "আল-আ'লা", "আল-গাশিয়াহ", "আল-ফাজর", "আল-বালাদ",
        "আশ-শামস", "আল-লাইল", "আদ-দুহা", "আল-ইনশিরাহ", "আত-তীন",
        "আল-আলাক", "আল-কাদর", "আল-বাইয়্যিনাহ", "আয-যিলযাল", "আল-আদিয়াত",
        "আল-কারি'আহ", "আত-তাকাসুর", "আল-আসর", "আল-হুমাজাহ", "আল-ফীল",
        "কুরাইশ", "আল-মাউন", "আল-কাওসার", "আল-কাফিরুন", "আন-নাসর",
        "আল-মাসাদ", "আল-ইখলাস", "আল-ফালাক", "আন-নাস"
    ];

    let suraHTML = '';
    suraNames.forEach((name, index) => {
        const suraNumber = index + 1;
        const ayahCount = getSurahAyahCount(suraNumber);
        suraHTML += `
            <div class="sura-item" data-sura="${suraNumber}" data-ayah-count="${ayahCount}">
                <strong>${suraNumber}</strong><br>${name}
                <small>(${ayahCount})</small>
            </div>
        `;
    });

    suraList.innerHTML = suraHTML;

    suraList.querySelectorAll('.sura-item').forEach(item => {
        item.addEventListener('click', function() {
            const suraNumber = this.getAttribute('data-sura');
            selectSura(suraNumber);
        });
    });
}

function selectSura(suraNumber) {
    const chatbotInput = document.getElementById('chatbot-input');
    if (chatbotInput) {
        chatbotInput.value = `${suraNumber}:1`;
        chatbotInput.focus();
        handleSendMessage();
    }
    document.getElementById('sura-panel').classList.remove('open');
}

// ==================== DAILY SECTION FUNCTIONS ====================
function initializeDailySection() {
    loadRandomAyat();

    const dailyButtons = document.querySelectorAll('.daily-section .btn');
    dailyButtons.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.preventDefault();
            const action = this.getAttribute('onclick');
            if (action) {
                eval(action);
            }
        });
    });
}

// ==================== ENHANCED CHATBOT FUNCTIONS ====================
function initializeEnhancedChatbot() {
    const chatbotBody = document.getElementById('chatbot-body');
    if (!chatbotBody) return;

    window.quranData = [];
    window.arabicData = [];
    window.tafsirData = {};
    window.currentAya = null;
    window.isLoading = false;
    window.isFullscreen = false;
    window.isVoiceActive = false;
    window.recognition = null;

    loadQuranData();
    setupChatbotEvents();
    setupTafsirButton();

    const fullscreenBtn = document.getElementById('fullscreen-btn');
    if (fullscreenBtn) {
        fullscreenBtn.addEventListener('click', toggleFullscreen);
    }

    const voiceBtn = document.getElementById('voice-btn');
    if (voiceBtn) {
        voiceBtn.addEventListener('click', toggleVoiceRecognition);
    }

    const audioBtn = document.getElementById('audio-button');
    if (audioBtn) {
        audioBtn.addEventListener('click', playCurrentAyaAudio);
    }
}

// ==================== TAFSIR MODAL FUNCTIONS ====================
function showTafsirModal(sura, aya) {
    const tafsirModal = document.getElementById('tafsir-modal');
    const tafsirContent = document.getElementById('tafsir-content');

    const tafsir = window.tafsirData[`${sura}:${aya}`];
    const arabic = window.arabicData.find(a => a.sura === sura && a.VerseIDAr === aya);
    const bengali = window.quranData.find(a => a.sura === sura && a.aya === aya);

    let contentHTML = '';

    if (arabic?.ayat) {
        contentHTML += `<div class="tafsir-verse">${arabic.ayat}</div>`;
    }

    if (bengali?.text) {
        contentHTML += `<div style="margin: 15px 0; padding: 15px; background: #f8f9fa; border-radius: 8px; border-left: 4px solid var(--primary);">
            <strong>বাংলা অনুবাদ:</strong><br>${bengali.text}
        </div>`;
    }

    if (tafsir?.text) {
        contentHTML += `<div class="tafsir-explanation">
            <strong>তাফসীর:</strong><br>${tafsir.text}
        </div>`;
    } else {
        contentHTML += `<div class="tafsir-explanation">
            <p>এই আয়াতের তাফসীর এখনও যোগ করা হয়নি।</p>
        </div>`;
    }

    contentHTML += `<div class="tafsir-source">
        <strong>উৎস:</strong> ইবনে কাসিরের তাফসীর
    </div>`;

    tafsirContent.innerHTML = contentHTML;
    tafsirModal.style.display = 'block';

    const fullscreenBtn = document.getElementById('tafsir-fullscreen-btn');
    fullscreenBtn.onclick = () => toggleTafsirFullscreen(sura, aya);

    const closeBtn = document.getElementById('tafsir-close-btn');
    closeBtn.onclick = closeTafsirModal;
}

function toggleTafsirFullscreen(sura, aya) {
    closeTafsirModal();
    showFullTafsir(sura, aya);
}

function closeTafsirModal() {
    const tafsirModal = document.getElementById('tafsir-modal');
    tafsirModal.style.display = 'none';
}

// ==================== ENHANCED FULLSCREEN TAFSIR MANAGEMENT ====================
function showFullTafsir(sura, aya) {
    const fullscreenTafsir = document.getElementById('fullscreen-tafsir');
    const tafsirText = document.getElementById('fullscreen-tafsir-text');

    const tafsir = window.tafsirData[`${sura}:${aya}`];
    const arabic = window.arabicData.find(a => a.sura === sura && a.VerseIDAr === aya);
    const bengali = window.quranData.find(a => a.sura === sura && a.aya === aya);

    let contentHTML = '';

    if (arabic?.ayat) {
        contentHTML += `<div class="arabic-text" lang="ar">${arabic.ayat}</div>`;
    }

    if (bengali?.text) {
        contentHTML += `<div style="padding: 1.5rem; background: var(--light-green); border-radius: var(--rounded); margin: 1rem 0; font-weight: 500; line-height: 1.6;">
            <strong>বাংলা অনুবাদ:</strong><br>${bengali.text}
        </div>`;
    }

    if (tafsir?.text) {
        contentHTML += `<div class="tafsir-container">${tafsir.text}</div>`;
    } else {
        contentHTML += `<div class="tafsir-container">
            <p>এই আয়াতের তাফসীর এখনও যোগ করা হয়নি।</p>
        </div>`;
    }

    tafsirText.innerHTML = contentHTML;
    fullscreenTafsir.classList.add('active');
    document.body.style.overflow = 'hidden';

    if (window.isFullscreen) {
        document.querySelector('.chatbot-section').style.display = 'none';
    }
}

function closeFullscreenTafsir() {
    const fullscreenTafsir = document.getElementById('fullscreen-tafsir');
    fullscreenTafsir.classList.remove('active');
    document.body.style.overflow = 'auto';

    if (window.isFullscreen) {
        document.querySelector('.chatbot-section').style.display = 'block';
    }
}

// ==================== TAFSIR BUTTON HANDLER ====================
function setupTafsirButton() {
    const tafsirButton = document.getElementById('tafsir-button');

    tafsirButton.addEventListener('click', function() {
        if (!window.currentAya) {
            const query = document.getElementById('chatbot-input').value.trim();
            const normalizedQuery = convertNumbers(query);
            const match = normalizedQuery.match(/^(\d+)[:\.\/,](\d+)$/);

            if (match) {
                window.currentAya = { sura: match[1], aya: match[2] };
            } else {
                addBotMessage('⚠️ প্রথমে একটি আয়াত সিলেক্ট করুন বা সূরা:আয়াত লিখুন', false, 'error');
                return;
            }
        }

        if (window.isFullscreen) {
            showTafsirModal(window.currentAya.sura, window.currentAya.aya);
        } else {
            showFullTafsir(window.currentAya.sura, window.currentAya.aya);
        }
    });
}

// ==================== FULLSCREEN FUNCTIONALITY ====================
function toggleFullscreen() {
    const chatbotHeader = document.getElementById('chatbot-header');
    const chatbotBody = document.getElementById('chatbot-body');
    const chatbotInputContainer = document.getElementById('chatbot-input-container');
    const fullscreenBtn = document.getElementById('fullscreen-btn');

    if (!window.isFullscreen) {
        chatbotHeader.classList.add('fullscreen');
        chatbotBody.classList.add('fullscreen');
        chatbotInputContainer.classList.add('fullscreen');

        fullscreenBtn.innerHTML = '<span>📺</span> সাধারণ মোড';
        fullscreenBtn.title = 'সাধারণ মোড';

        document.body.style.overflow = 'hidden';

        window.isFullscreen = true;
    } else {
        exitFullscreenMode();
    }
}

function exitFullscreenMode() {
    const chatbotHeader = document.getElementById('chatbot-header');
    const chatbotBody = document.getElementById('chatbot-body');
    const chatbotInputContainer = document.getElementById('chatbot-input-container');
    const fullscreenBtn = document.getElementById('fullscreen-btn');

    chatbotHeader.classList.remove('fullscreen');
    chatbotBody.classList.remove('fullscreen');
    chatbotInputContainer.classList.remove('fullscreen');

    fullscreenBtn.innerHTML = '<span>📺</span> ফুলস্ক্রিন';
    fullscreenBtn.title = 'ফুলস্ক্রিন';

    document.body.style.overflow = '';

    window.isFullscreen = false;

    closeTafsirModal();
}

// ==================== VOICE RECOGNITION ====================
function initializeVoiceRecognition() {
    if ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window) {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        window.recognition = new SpeechRecognition();
        window.recognition.continuous = false;
        window.recognition.interimResults = false;
        window.recognition.lang = 'bn-BD';

        window.recognition.onstart = function() {
            addBotMessage('🎤 কথা বলুন... আমি শুনছি।', false, 'info');
            document.getElementById('voice-btn').innerHTML = '<span>🔴</span> রেকর্ডিং';
        };

        window.recognition.onresult = function(event) {
            const transcript = event.results[0][0].transcript;
            document.getElementById('chatbot-input').value = transcript;
            addUserMessage(transcript);
            processUserQuery(transcript);
        };

        window.recognition.onerror = function(event) {
            addBotMessage('❌ ভয়েস রেকগনিশনে সমস্যা: ' + event.error, false, 'error');
            window.isVoiceActive = false;
            document.getElementById('voice-btn').innerHTML = '<span>🎤</span> ভয়েস';
        };

        window.recognition.onend = function() {
            window.isVoiceActive = false;
            document.getElementById('voice-btn').innerHTML = '<span>🎤</span> ভয়েস';
        };
    } else {
        addBotMessage('❌ আপনার ব্রাউজার ভয়েস রেকগনিশন সাপোর্ট করে না।', false, 'error');
    }
}

function toggleVoiceRecognition() {
    if (!window.recognition) {
        initializeVoiceRecognition();
    }

    if (!window.isVoiceActive) {
        try {
            window.recognition.start();
            window.isVoiceActive = true;
        } catch (error) {
            addBotMessage('❌ মাইক্রোফোন এক্সেস করতে সমস্যা।', false, 'error');
        }
    } else {
        window.recognition.stop();
        window.isVoiceActive = false;
    }
}

// ==================== QURAN DATA LOADING ====================
async function loadQuranData() {
    try {
        showLoadingState(true);

        const [quranRes, arabicRes, tafsirRes] = await Promise.all([
            fetch("https://raw.githubusercontent.com/Akter-Molla/Quran-bot-bn/main/ayats_bn.json"),
            fetch("https://raw.githubusercontent.com/alQuranBD/Database/master/json/ayats_ar.json"),
            fetch("https://raw.githubusercontent.com/Akter-Molla/Quran-bot-bn/main/Tafseer_ibn_Kathir.json")
        ]);

        if (!quranRes.ok || !arabicRes.ok || !tafsirRes.ok) {
            throw new Error('ডেটা লোড করতে সমস্যা হয়েছে');
        }

        window.quranData = await quranRes.json();
        window.arabicData = await arabicRes.json();
        window.tafsirData = await tafsirRes.json();

        addBotMessage('✅ কুরআন ডেটা সফলভাবে লোড হয়েছে! এখন আপনি আয়াত বা তাফসীর খুঁজতে পারেন।');

    } catch (error) {
        console.error('ডেটা লোডিং ত্রুটি:', error);
        addBotMessage('❌ ডেটা লোড করতে সমস্যা হয়েছে। দয়া করে পৃষ্ঠাটি রিফ্রেশ করুন।', false, 'error');
    } finally {
        showLoadingState(false);
    }
}

// ==================== CHATBOT EVENT HANDLERS ====================
function setupChatbotEvents() {
    const sendButton = document.getElementById('send-button');
    const chatbotInput = document.getElementById('chatbot-input');
    const clearButton = document.getElementById('clear-button');
    const audioButton = document.getElementById('audio-button');

    if (sendButton) {
        sendButton.addEventListener('click', handleSendMessage);
    }

    if (chatbotInput) {
        chatbotInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSendMessage();
            }
        });
        chatbotInput.focus();
    }

    if (clearButton) {
        clearButton.addEventListener('click', clearChat);
    }

    if (audioButton) {
        audioButton.addEventListener('click', playCurrentAyaAudio);
    }

    document.addEventListener('click', function(e) {
        if (e.target.matches('.quick-action-btn') || e.target.closest('.quick-action-btn')) {
            const button = e.target.matches('.quick-action-btn') ? e.target : e.target.closest('.quick-action-btn');
            const action = button.getAttribute('data-action');
            handleQuickAction(action);
        }
    });

    const exitFullscreen = document.getElementById('exit-fullscreen');
    if (exitFullscreen) {
        exitFullscreen.addEventListener('click', closeFullscreenTafsir);
    }

    const copyTafsirBtn = document.getElementById('copy-tafsir-btn');
    if (copyTafsirBtn) {
        copyTafsirBtn.addEventListener('click', copyTafsirText);
    }

    const shareTafsirBtn = document.getElementById('share-tafsir-btn');
    if (shareTafsirBtn) {
        shareTafsirBtn.addEventListener('click', shareTafsir);
    }
}

// ==================== MESSAGE HANDLING ====================
function handleSendMessage() {
    if (window.isLoading) return;

    const chatbotInput = document.getElementById('chatbot-input');
    const query = chatbotInput.value.trim();

    if (!query) {
        addBotMessage('❌ অনুগ্রহ করে একটি প্রশ্ন বা আয়াত নম্বর লিখুন।', false, 'error');
        return;
    }

    addUserMessage(query);
    chatbotInput.value = '';
    chatbotInput.focus();

    processUserQuery(query);
}

function processUserQuery(query) {
    showTypingIndicator();

    setTimeout(() => {
        removeTypingIndicator();

        try {
            const normalizedQuery = convertNumbers(query);

            if (isSurahAyaPattern(normalizedQuery)) {
                handleSurahAyaQuery(normalizedQuery);
            } else if (isKeywordSearch(normalizedQuery)) {
                handleKeywordSearch(normalizedQuery);
            } else if (isGreeting(query)) {
                handleGreeting(query);
            } else if (isPrayerTimeQuery(query)) {
                handlePrayerTimeQuery(query);
            } else if (isQuizQuery(query)) {
                handleQuizQuery(query);
            } else {
                handleGeneralQuery(query);
            }
        } catch (error) {
            console.error('Query processing error:', error);
            addBotMessage('❌ প্রশ্ন প্রক্রিয়াকরণে সমস্যা হয়েছে। দয়া করে আবার চেষ্টা করুন।', false, 'error');
        }
    }, 1000);
}

function handleQuickAction(action) {
    showTypingIndicator();

    setTimeout(() => {
        removeTypingIndicator();

        switch(action) {
            case 'about':
                showAboutBot();
                break;
            case 'guide':
                showUsageGuide();
                break;
            case 'start':
                startChat();
                break;
            case 'popular':
                showPopularAyat();
                break;
            case 'prayer':
                showPrayerTimes();
                break;
            case 'quiz':
                startQuranQuiz();
                break;
        }
    }, 500);
}

// ==================== SEARCH FUNCTIONS ====================
function handleKeywordSearch(query) {
    const results = searchQuranWithCount(query);

    if (results.length === 0) {
        addBotMessage(`❌ "${query}" এর জন্য কোন ফলাফল পাওয়া যায়নি। দয়া করে ভিন্ন শব্দ দিয়ে চেষ্টা করুন।`, false, 'error');
    } else if (results.length === 1) {
        window.currentAya = results[0];
        displayAyaResult(results[0]);
    } else {
        displayWordSearchResults(results, query);
    }
}

function searchQuranWithCount(query) {
    const normalizedQuery = convertNumbers(query);
    const words = normalizedQuery.toLowerCase().split(/\s+/);
    const searchResults = [];

    window.quranData.forEach(aya => {
        const text = aya.text.toLowerCase();
        let matchCount = 0;
        let highlightedText = aya.text;

        words.forEach(word => {
            const regex = new RegExp(word, 'gi');
            const matches = text.match(regex);
            if (matches) {
                matchCount += matches.length;
                highlightedText = highlightedText.replace(regex, match => `<span class="search-highlight">${match}</span>`);
            }
        });

        if (matchCount > 0) {
            searchResults.push({
                ...aya,
                matchCount: matchCount,
                highlightedText: highlightedText
            });
        }
    });

    searchResults.sort((a, b) => b.matchCount - a.matchCount);

    return searchResults.slice(0, 10);
}

function displayWordSearchResults(results, query) {
    const totalMatches = results.reduce((sum, result) => sum + result.matchCount, 0);

    let resultsHTML = `
        <div class="word-search-results">
            <div class="word-search-header">
                <strong>"${query}" এর জন্য ${results.length}টি আয়াত পাওয়া গেছে</strong>
                <span class="word-search-count">মোট ${totalMatches}টি মিল</span>
            </div>
            <div style="max-height: 300px; overflow-y: auto; padding-right: 10px;">`;

    results.forEach((aya, index) => {
        resultsHTML += `
            <div class="search-result-item">
                <div class="search-result-sura">
                    ${index + 1}. সূরা ${aya.sura}, আয়াত ${aya.aya}
                    <small style="color: var(--gray-dark); margin-left: 10px;">(${aya.matchCount}টি মিল)</small>
                </div>
                <div class="search-result-text">${aya.highlightedText}</div>
                <button onclick="selectAyaFromSearch('${aya.sura}', '${aya.aya}')" 
                        style="margin-top: 10px; background: var(--gold); color: black; border: none; padding: 8px 12px; border-radius: 5px; cursor: pointer; font-size: 0.9em; font-weight: 600;">
                    নির্বাচন করুন
                </button>
            </div>`;
    });

    if (results.length > 10) {
        resultsHTML += `<div style="text-align: center; margin-top: 15px; color: var(--gray-dark); font-style: italic;">
            ... এবং আরও ${results.length - 10}টি ফলাফল
        </div>`;
    }

    resultsHTML += `</div></div>`;
    addBotMessage(resultsHTML, true);
}

