        const query = `${randomSurah}:${randomAyah}`;
        handleSurahAyaQuery(query);

        addBotMessage(`🎲 র‍্যান্ডম আয়াত: সূরা ${randomSurah}, আয়াত ${randomAyah}`, false, 'info');
