// ==================== QUIZ FUNCTIONS ====================
function isQuizQuery(query) {
    const quizKeywords = ['কুইজ', 'quiz', 'প্রশ্ন', 'পরীক্ষা', 'test', 'জ্ঞান'];
    return quizKeywords.some(keyword => query.toLowerCase().includes(keyword));
}

function handleQuizQuery(query) {
    startQuranQuiz();
}

function startQuranQuiz() {
    const quizQuestions = [
        {
            question: "কুরআনের প্রথম সূরার নাম কি?",
            options: ["আল-ফাতিহা", "আল-বাকারা", "আল-ইখলাস", "ইয়াসিন"],
            correct: 0,
            explanation: "কুরআনের প্রথম সূরার নাম আল-ফাতিহা, যার অর্থ 'উন্মোচনকারী'। এটি ৭টি আয়াত নিয়ে গঠিত।"
        },
        {
            question: "কুরআনে মোট কয়টি সূরা আছে?",
            options: ["114", "100", "125", "99"],
            correct: 0,
            explanation: "কুরআনে মোট ১১৪টি সূরা আছে, যার মধ্যে ৮৬টি মাক্কী এবং ২৮টি মাদানী সূরা।"
        },
        {
            question: "আয়াতুল কুরসি কোন সূরায় আছে?",
            options: ["সূরা বাকারা", "সূরা ইখলাস", "সূরা ফাতিহা", "সূরা ইয়াসিন"],
            correct: 0,
            explanation: "আয়াতুল কুরসি সূরা বাকারার ২৫৫ নম্বর আয়াত। এটি কুরআনের সবচেয়ে বড় আয়াত।"
        },
        {
            question: "কুরআনের দীর্ঘতম সূরার নাম কি?",
            options: ["আল-বাকারা", "আল-ইমরান", "আন-নিসা", "আল-মায়িদাহ"],
            correct: 0,
            explanation: "আল-বাকারা কুরআনের দীর্ঘতম সূরা, যাতে ২৮৬টি আয়াত আছে।"
        },
        {
            question: "কুরআনের ক্ষুদ্রতম সূরার নাম কি?",
            options: ["আল-কাওসার", "আল-ইখলাস", "আন-নাস", "আল-ফালাক"],
            correct: 0,
            explanation: "আল-কাওসার কুরআনের ক্ষুদ্রতম সূরা, যাতে মাত্র ৩টি আয়াত আছে।"
        }
    ];

    let currentQuestion = 0;
    let score = 0;

    function askQuestion() {
        if (currentQuestion >= quizQuestions.length) {
            showQuizResult();
            return;
        }

        const q = quizQuestions[currentQuestion];
        let quizHTML = `
            <strong>🧠 কুরআন কুইজ (${currentQuestion + 1}/${quizQuestions.length})</strong><br><br>
            <strong>প্রশ্ন:</strong> ${q.question}<br><br>
        `;

        q.options.forEach((option, index) => {
            quizHTML += `
                <button onclick="checkAnswer(${index}, ${currentQuestion})" 
                        style="display: block; width: 100%; margin: 5px 0; padding: 10px; border: 1px solid var(--primary); border-radius: 5px; background: var(--light-green); cursor: pointer;">
                    ${String.fromCharCode(65 + index)}. ${option}
                </button>
            `;
        });

        addBotMessage(quizHTML, true);
    }

    window.checkAnswer = function(selected, questionIndex) {
        const q = quizQuestions[questionIndex];
        if (selected === q.correct) {
            score++;
            addBotMessage(`✅ সঠিক উত্তর! 🎉<br><br><strong>ব্যাখ্যা:</strong> ${q.explanation}`, false, 'success');
        } else {
            addBotMessage(`❌ ভুল উত্তর! সঠিক উত্তর: ${q.options[q.correct]}<br><br><strong>ব্যাখ্যা:</strong> ${q.explanation}`, false, 'error');
        }

        currentQuestion++;
        setTimeout(askQuestion, 2000);
    };

    function showQuizResult() {
        const percentage = Math.round((score / quizQuestions.length) * 100);
        let message = '';

        if (percentage >= 80) {
            message = '🎉 অসাধারণ! আপনি কুরআন সম্পর্কে গভীর জ্ঞান রাখেন। আল্লাহ আপনাকে আরও বরকত দান করুন।';
        } else if (percentage >= 60) {
            message = '👍 ভালো হয়েছে! আরও পড়াশোনা করে আপনার জ্ঞান বৃদ্ধি করুন।';
        } else {
            message = '📚 আরও পড়ুন এবং শিখুন। আল্লাহ আপনাকে কুরআন বুঝার তাওফিক দান করুন।';
        }

        addBotMessage(`
            <strong>📊 কুইজ রেজাল্ট</strong><br><br>
            <strong>স্কোর:</strong> ${score}/${quizQuestions.length}<br>
            <strong>পার্সেন্টেজ:</strong> ${percentage}%<br><br>
            ${message}<br><br>
            <button onclick="startQuranQuiz()" style="background: var(--primary); color: white; border: none; padding: 10px 20px; border-radius: 5px; cursor: pointer; font-weight: 600;">
                🔄 আবার চেষ্টা করুন
            </button>
        `, true);

        delete window.checkAnswer;
    }

    askQuestion();
}

// ==================== UTILITY FUNCTIONS ====================
function convertNumbers(input) {
    const bnToEn = {'০':'0','১':'1','২':'2','৩':'3','৪':'4','৫':'5','৬':'6','৭':'7','৮':'8','৯':'9'};
    let output = input;
    for (const [bn, en] of Object.entries(bnToEn)) {
        output = output.replace(new RegExp(bn, 'g'), en);
    }
    return output;
}

function isSurahAyaPattern(query) {
    return /^(\d+)[:\.\/,](\d+)$/.test(query) || 
           /^সূরা\s*(\d+)\s*আয়াত\s*(\d+)$/i.test(query);
}

function isKeywordSearch(query) {
    return query.length >= 2 && !isGreeting(query);
}

function isGreeting(query) {
    const greetings = ['সালাম', 'assalam', 'hello', 'hi', 'hola', 'নমস্কার', 'আদাব'];
    return greetings.some(greet => query.toLowerCase().includes(greet.toLowerCase()));
}

// ==================== DISPLAY FUNCTIONS ====================
function addUserMessage(message) {
    const chatbotBody = document.getElementById('chatbot-body');
    const messageDiv = document.createElement('div');
    messageDiv.className = 'message user';
    messageDiv.innerHTML = message + `<div class="message-timestamp">${getCurrentTimestamp()}</div>`;
    chatbotBody.appendChild(messageDiv);
    scrollToBottom();
}

function addBotMessage(message, isHTML = false, type = 'normal') {
    const chatbotBody = document.getElementById('chatbot-body');
    const messageDiv = document.createElement('div');
    messageDiv.className = `message bot ${type === 'error' ? 'error' : type === 'success' ? 'success' : type === 'info' ? 'info' : ''}`;

    if (isHTML) {
        messageDiv.innerHTML = message + `<div class="message-timestamp">${getCurrentTimestamp()}</div>`;
    } else {
        messageDiv.innerHTML = message + `<div class="message-timestamp">${getCurrentTimestamp()}</div>`;
    }

    chatbotBody.appendChild(messageDiv);
    scrollToBottom();
}

function showTypingIndicator() {
    const chatbotBody = document.getElementById('chatbot-body');
    const typingDiv = document.createElement('div');
    typingDiv.id = 'typing-indicator';
    typingDiv.className = 'message bot typing';
    typingDiv.innerHTML = '<div class="typing-dots"><span></span><span></span><span></span></div>';
    chatbotBody.appendChild(typingDiv);
    scrollToBottom();
}

function removeTypingIndicator() {
    const typingIndicator = document.getElementById('typing-indicator');
    if (typingIndicator) {
        typingIndicator.remove();
    }
}

function scrollToBottom() {
    const chatbotBody = document.getElementById('chatbot-body');
    if (chatbotBody) {
        chatbotBody.scrollTop = chatbotBody.scrollHeight;
    }
}

function showLoadingState(show) {
    window.isLoading = show;
    const sendButton = document.getElementById('send-button');
    const chatbotInput = document.getElementById('chatbot-input');

    if (sendButton) {
        sendButton.disabled = show;
        sendButton.innerHTML = show ? '<span>⏳</span> লোড হচ্ছে...' : '<span>📤</span> পাঠান';
    }

    if (chatbotInput) {
        chatbotInput.disabled = show;
    }
}

function clearChat() {
    const chatbotBody = document.getElementById('chatbot-body');
    if (chatbotBody) {
        chatbotBody.innerHTML = `
            <div class="message bot">
                <strong>🤲 আসসালামু আলাইকুম!</strong><br/>
                কুরআনের আয়াত, তাফসীর ও হাদিস সম্পর্কে জানুন। নিচের বাটনগুলো ক্লিক করে শুরু করুন...
                <div class="message-timestamp">${getCurrentTimestamp()}</div>
            </div>
            <div class="quick-actions">
                <button class="quick-action-btn" data-action="about">🤖 বট সম্পর্কে</button>
                <button class="quick-action-btn" data-action="guide">📖 ব্যবহার গাইড</button>
                <button class="quick-action-btn" data-action="start">💬 চ্যাট শুরু</button>
                <button class="quick-action-btn" data-action="popular">⭐ জনপ্রিয় আয়াত</button>
                <button class="quick-action-btn secondary" data-action="prayer">🕌 সালাত সময়</button>
                <button class="quick-action-btn secondary" data-action="quiz">🧠 কুরআন কুইজ</button>
            </div>
        `;
    }

    window.currentAya = null;
    const chatbotInput = document.getElementById('chatbot-input');
    if (chatbotInput) {
        chatbotInput.value = '';
